p=argparse.ArgumentParser();p.add_argument('--executable',required=True,type=pathlib.Path);p.add_argument('--directory',required=True,type=pathlib.Path);p.add_argument('--sdk-directory',required=True,type=pathlib.Path);p.add_argument('--node',required=True);p.add_argument('--library',required=True);a=p.parse_args();a.directory.mkdir(parents=True,exist_ok=True);out=pathlib.Path(tempfile.mkdtemp(prefix="run-",dir=a.directory));sdk=a.sdk_directory.resolve();suite=out/'suite.mjs';suite.write_text("import{defineNativeSuite}from "+json.dumps((sdk/'native.js').as_uri())+";import{closeSync,existsSync,writeFileSync}from'node:fs';import{setTimeout as wait}from'node:timers/promises';export default defineNativeSuite({tests:[{title:'actual raw callback returned with pending native file fence',timeout:3000,run:(_,i)=>{void i.attach('held',{body:'actual pending bytes'});void(async()=>{while(!existsSync(process.env.SUITECUT_ATTACHMENT_TEST_MARKER))await wait(1);await wait(100);writeFileSync(process.env.ACTUAL_BODY_TIMER,String(process.pid));closeSync(3);Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,60);process.exit(0)})();}}]});")
